    props: { type: 'text', placeholder: '输入访问密码' },
  },
  {
    key: 'mode',
    label: '任务类型',
    type: 'select',
    span: 12,
    options: [
      { label: '日常巡防', value: 'patrol' },
      { label: '应急支援', value: 'support' },
    ],
  },
  {
    key: 'officer',
    label: '负责人',
    type: 'remote-select',
    span: 12,
    options: candidateOptions.value,
    props: {
      filterable: true,
      remote: true,
      debounce: 0,
      remoteMethod: loadCandidates,
      loading: candidateStatus.value === 'loading',
      placeholder: '搜索候选人员',
    },
    feedback: candidateFeedback(),
  },
  {
    key: 'enabled',
    label: '启用任务',
    type: 'switch',
    span: 12,
  },
  {
    key: 'supportNote',
    label: '支援说明',
    type: 'textarea',
    span: 24,
    visible: (model) => model.mode === 'support',
    props: { rows: 2, placeholder: '填写支援范围' },
  },
  {
    key: 'cover',
    label: '任务封面（单张）',
    type: 'upload',
    sectionTitleBefore: '附件',
    span: 12,
    props: {
      accept: 'image/*',
      autoUpload: true,
      drag: true,
      httpRequest: mockImageUpload,
      limit: 1,
      maxSize: 10,
    },
  },
  {
    key: 'photos',
    label: '现场图片（多张）',
    type: 'upload',
    span: 24,
    props: {
      accept: 'image/*',
