    span: 12,
  },
  {
    key: 'supportNote',
    label: '支援说明',
    type: 'textarea',
    span: 24,
    visible: (model) => model.mode === 'support',
    props: { rows: 2, placeholder: '填写支援范围' },
  },
  {
    key: 'cover',
    label: '任务封面（单张）',
    type: 'upload',
    sectionTitleBefore: '附件',
    span: 12,
    props: {
      accept: 'image/*',
      autoUpload: true,
